"""Write the example netlists of deliverable 2 into netlists/.

* One single-transistor netlist per case (NMOS ON/OFF, PMOS ON/OFF): every
  terminal has its own voltage source; nominal model card, VDD = 0.9 V,
  27 C; the terminal currents are printed with the sign convention of the
  datasets (current into the terminal, I = -i(Vsource)).
* One netlist per gate (INV, NAND2, NOR2, AND2, OR2), generated by the same
  function as the Part B validation (gate_validation.make_netlist), at the
  nominal corner and Wn = 2*Lmin, Wp = 4*Lmin. Change the input-source
  values to simulate another input combination.
* The test-circuit netlist (netlists/parity8.cir) is written by
  src/validation/circuit_validation.py.

All netlists include "models/16nm_LP.pm", so run them from the project root:

    ngspice_con.exe -b netlists/nmos_off.cir
    python .\\src\\spice\\write_example_netlists.py --check --ngspice ngspice_con.exe
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "src"))
sys.path.insert(0, str(ROOT / "src" / "validation"))
import gate_validation as gv  # noqa: E402

NETLIST_DIR = ROOT / "netlists"
MODEL_INCLUDE = "models/16nm_LP.pm"
VDD, TEMP, LMIN = 0.9, 27.0, 16e-9
OPTIONS = ".options gmin=1e-18 abstol=1e-18 reltol=1e-6 vntol=1e-9"

# case: (transistor, vd, vg, vs, vb, width) at a typical in-gate bias
TRANSISTOR_CASES = {
    "nmos_on":  ("nmos", 0.45, VDD, 0.0, 0.0, 2 * LMIN),
    "nmos_off": ("nmos", VDD, 0.0, 0.0, 0.0, 2 * LMIN),
    "pmos_on":  ("pmos", 0.45, 0.0, VDD, VDD, 4 * LMIN),
    "pmos_off": ("pmos", 0.0, VDD, VDD, VDD, 4 * LMIN),
}
GATE_INPUTS = {"INV": "1", "NAND2": "10", "NOR2": "10", "AND2": "10", "OR2": "10"}


def transistor_netlist(case: str) -> str:
    transistor, vd, vg, vs, vb, width = TRANSISTOR_CASES[case]
    return "\n".join([
        f"* Single-transistor netlist: {case.upper().replace('_', ' ')}",
        "* 16nm LP, nominal model card, VDD = 0.9 V, 27 C",
        f'.include "{MODEL_INCLUDE}"',
        OPTIONS,
        f".temp {TEMP:g}",
        "* every terminal has its own voltage source",
        f"VDS d 0 DC {vd:g}",
        f"VGS g 0 DC {vg:g}",
        f"VSS s 0 DC {vs:g}",
        f"VBS b 0 DC {vb:g}",
        f"M1 d g s b {transistor} L={LMIN:g} W={width:g}",
        ".control",
        "op",
        "* current INTO each terminal (dataset sign convention)",
        "let Id = -i(VDS)", "let Ig = -i(VGS)", "let Is = -i(VSS)", "let Ib = -i(VBS)",
        "print Id", "print Ig", "print Is", "print Ib",
        "let KCL = Id + Ig + Is + Ib", "print KCL",
        "quit", ".endc", ".end", "",
    ])


def gate_netlist(gate: str) -> str:
    bits = GATE_INPUTS[gate]
    corner = {"vdd": VDD, "temp": TEMP}
    widths = {"nmos": gv.DEFAULT_WN, "pmos": gv.DEFAULT_WP}
    body = gv.make_netlist(gate, bits, corner, widths).replace("{MODEL}", MODEL_INCLUDE)
    header = (f"* {gate} gate netlist (static CMOS), inputs {bits}, nominal corner "
              f"(VDD = 0.9 V, 27 C), Wn = 2*Lmin, Wp = 4*Lmin\n"
              "* Same netlist as the Part B validation; leakage = |i(VDD)|.\n")
    return header + body


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true", help="run every netlist in ngspice")
    parser.add_argument("--ngspice", default="ngspice_con.exe")
    args = parser.parse_args()

    NETLIST_DIR.mkdir(exist_ok=True)
    written = []
    for case in TRANSISTOR_CASES:
        path = NETLIST_DIR / f"{case}.cir"
        path.write_text(transistor_netlist(case))
        written.append(path)
    for gate in GATE_INPUTS:
        path = NETLIST_DIR / f"gate_{gate.lower()}.cir"
        path.write_text(gate_netlist(gate))
        written.append(path)
    for path in written:
        line = f"  {path.relative_to(ROOT)}"
        if args.check:
            done = subprocess.run([args.ngspice, "-b", str(path.relative_to(ROOT))], cwd=ROOT,
                                  capture_output=True, text=True, check=False)
            out = done.stdout
            values = re.findall(r"(?im)^(id|ig|is|ib|kcl|i\(vdd\)|v\(\w+\))\s*=\s*(\S+)", out)
            ok = done.returncode == 0 and values
            line += ("   OK  " + "  ".join(f"{k}={v}" for k, v in values)) if ok else "   FAILED"
        print(line)


if __name__ == "__main__":
    main()
